class RecordVectorTests(unittest.TestCase):
    def test_18_literal_complete_records(self):
        values=fixtures();values['ReviewPacket']=packet_with_views()
        self.assertEqual(18,len(RECORD_VECTORS))
        for kind,wire,expected in RECORD_VECTORS:
            with self.subTest(kind=kind):
                record=values[kind]
                self.assertEqual(record,json.loads(wire))
                self.assertEqual(record,validate_si_record(record))
                self.assertEqual(wire,canonical_si_json(record))
                self.assertEqual(expected,si_record_ref(record))
                self.assertEqual(expected,validate_si_record_ref(record,expected))

    def test_R1b_literal_field_values(self):
        import hashlib
        for name,value,wire,expected_sha in VALUE_VECTORS:
            with self.subTest(name=name):
                self.assertEqual(wire,canonical_si_json(value))
                self.assertEqual(expected_sha,hashlib.sha256(wire).hexdigest())
        # eligibility.state is a STATE FieldView; it is deliberately not a grant.
        self.assertEqual('STATE',VALUE_VECTORS[-1][1]['kind'])
        self.assertNotIn('source_ref',VALUE_VECTORS[-1][1])

    def test_shared_canonical_S1_byte_parity(self):
        for _,wire,_ in RECORD_VECTORS:
            value=json.loads(wire)
            self.assertEqual(wire,s1_json(value))
            self.assertEqual(wire,canonical_si_json(value))


if __name__=='__main__':unittest.main()
